import EnvironmentLightState from './EnvironmentLightState.js';
import type Texture from './Texture.js';

/**
 * Image-based lighting from an equirectangular (latitude-longitude) HDR map,
 * loaded with `loadRGBE()` or generated by `ProceduralSky`. Importance sampled.
 * `transform` rotates the environment from local to world space (default identity);
 * translation and positive axis scale are ignored.
 */
export default class EnvironmentLight extends EnvironmentLightState {
  /** Equirectangular radiance map in linear color. The first row is the zenith (+Y); `flipY` is ignored. */
  declare map: Texture;
  constructor(params: { /** Required equirectangular radiance map; no default. */ map: Texture;
    /** Nonnegative radiance multiplier; zero disables this light. Default `1`. */ intensity?: number }) { super(params); }
}
